// scripts/plot-performance.mjs — the Section 4 figures, drawn from the harness CSV.
//
// test-performance.html draws its own charts for reading a run. These are the manuscript's: same
// data, print sizing, no interactivity, and regenerated by rerunning this script, so every point in
// a figure traces to rows in the file named on the command line.
//
//     node scripts/plot-performance.mjs performance.csv
//     node scripts/plot-performance.mjs performance.csv --out=figures --prefix=fig-4
//
// One SVG per figure, 1160 units wide to match the Section 3 figures at a 190 mm double-column
// placement, with no external fonts and no color carrying information that lightness does not also
// carry (each series has its own marker as well as its own hue).
//
// Written figures, when the CSV holds the rows for them:
//     <prefix>-reuse.svg        t_reuse and t_redecode against k, per rung
//     <prefix>-throughput.svg   cells per second against grid size, per analysis case
//     <prefix>-decode.svg       decode time against grid size, cold and warm
//     <prefix>-map-<metric>.svg map boot, first render and restyle against grid size, per provider
//
// The reuse figure also prints the least-squares fit of each series to the console: re-decode is
// linear in k with a slope equal to the decode time, and reuse is flat. Those two numbers are the
// section's claim, so they are reported rather than left to the reader's eye.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const args = process.argv.slice(2);
const CSV = args.find((a) => !a.startsWith("--")) ?? "performance.csv";
const opt = (name, dflt) => args.find((a) => a.startsWith(`--${name}=`))?.slice(name.length + 3) ?? dflt;
const OUT = opt("out", "figures");
const PREFIX = opt("prefix", "fig-4");

// ── the file ──────────────────────────────────────────────────────────────────────────────────
// A minimal CSV reader: the harness quotes only the user-agent field, and only for its commas.
function parseCSV(text) {
  const lines = text.trim().split(/\r?\n/);
  const head = lines[0].split(",");
  return lines.slice(1).map((line) => {
    const cells = [];
    let cur = "", quoted = false;
    for (let i = 0; i < line.length; i++) {
      const c = line[i];
      if (quoted) {
        if (c === '"' && line[i + 1] === '"') { cur += '"'; i++; }
        else if (c === '"') quoted = false;
        else cur += c;
      } else if (c === '"') quoted = true;
      else if (c === ",") { cells.push(cur); cur = ""; }
      else cur += c;
    }
    cells.push(cur);
    return Object.fromEntries(head.map((h, i) => [h, cells[i]]));
  });
}

const rows = parseCSV(readFileSync(CSV, "utf8")).map((r) => ({
  ...r, cells: +r.cells, value: +r.value, session: r.session ?? "",
}));

const median = (a) => {
  const s = [...a].sort((x, y) => x - y);
  const i = (s.length - 1) / 2;
  return s.length % 2 ? s[i] : (s[Math.floor(i)] + s[Math.ceil(i)]) / 2;
};
const med = (f) => {
  const v = rows.filter(f).map((r) => r.value);
  return v.length ? median(v) : null;
};
const cellsRun = [...new Set(rows.map((r) => r.cells))].filter((c) => c > 0).sort((a, b) => a - b);
const label = (c) => (c >= 1e6 ? `${(c / 1e6).toFixed(1)}M cells` : `${(c / 1000).toFixed(0)}k cells`);

// ── the chart ─────────────────────────────────────────────────────────────────────────────────
const INK = "#1a1d21", MUTED = "#5b6570", RULE = "#b8c0c8", GRID = "#e8ecf0";
const COLORS = ["#1f4e79", "#c0504d", "#4f8a3d", "#8064a2", "#e08a1e", "#3a8f9c"];
const MARKS = ["circle", "square", "triangle", "diamond", "circle", "square"];

// The callers pass fixed-precision strings, so the coordinates are coerced here. "123.4" + 4.6 is
// string concatenation, and a polygon built from that covers the whole plot.
function marker(kind, xIn, yIn, fill) {
  const x = +xIn, y = +yIn;
  if (kind === "square") return `<rect x="${x - 4}" y="${y - 4}" width="8" height="8" fill="${fill}"/>`;
  if (kind === "triangle") return `<polygon points="${x},${y - 5} ${x + 4.6},${y + 3.5} ${x - 4.6},${y + 3.5}" fill="${fill}"/>`;
  if (kind === "diamond") return `<polygon points="${x},${y - 5.4} ${x + 4.6},${y} ${x},${y + 5.4} ${x - 4.6},${y}" fill="${fill}"/>`;
  return `<circle cx="${x}" cy="${y}" r="4.5" fill="${fill}"/>`;
}

function chart({ xLabel, yLabel, series, logX = false, logY = false, w = 1160, h = 520 }) {
  const pad = { l: 96, r: 26, t: 26, b: 62 };
  const pts = series.flatMap((s) => s.points);
  if (!pts.length) return null;
  const fx = (v) => (logX ? Math.log10(v) : v);
  const x0 = Math.min(...pts.map((p) => fx(p[0]))), x1 = Math.max(...pts.map((p) => fx(p[0])));
  // A rate axis spanning 14 Mcells/s to 1.2 Gcells/s flattens every series but the fastest on a
  // linear scale, so the caller can ask for decades instead.
  const yv = pts.map((p) => p[1]);
  const yLo = logY ? Math.floor(Math.log10(Math.min(...yv))) : 0;
  const yHi = logY ? Math.ceil(Math.log10(Math.max(...yv))) : Math.max(...yv) * 1.1;
  const X = (v) => pad.l + ((fx(v) - x0) / ((x1 - x0) || 1)) * (w - pad.l - pad.r);
  const Y = (v) => {
    const f = logY ? (Math.log10(v) - yLo) / ((yHi - yLo) || 1) : v / (yHi || 1);
    return h - pad.b - f * (h - pad.t - pad.b);
  };

  const yticks = logY
    ? Array.from({ length: yHi - yLo + 1 }, (_, i) => 10 ** (yLo + i))
    : [0, 0.25, 0.5, 0.75, 1].map((f) => f * yHi);
  const xticks = [...new Set(pts.map((p) => p[0]))].sort((a, b) => a - b);
  const fmtY = (v) => (v >= 1000 ? (v / 1000).toFixed(v >= 10000 ? 0 : 1) + "k"
    : v >= 10 ? v.toFixed(0) : v >= 1 ? v.toFixed(1) : v.toFixed(v >= 0.1 ? 2 : 3));
  const fmtX = (v) => (v >= 1e6 ? (v / 1e6).toFixed(1) + "M" : v >= 1000 ? (v / 1000).toFixed(0) + "k" : String(v));

  const body = [
    ...yticks.map((t) => `<line x1="${pad.l}" x2="${w - pad.r}" y1="${Y(t).toFixed(1)}" y2="${Y(t).toFixed(1)}" stroke="${GRID}"/>` +
      `<text x="${pad.l - 12}" y="${(Y(t) + 5).toFixed(1)}" text-anchor="end" font-size="15" fill="${MUTED}">${fmtY(t)}</text>`),
    `<line x1="${pad.l}" x2="${w - pad.r}" y1="${h - pad.b}" y2="${h - pad.b}" stroke="${RULE}" stroke-width="1.2"/>`,
    `<line x1="${pad.l}" x2="${pad.l}" y1="${pad.t}" y2="${h - pad.b}" stroke="${RULE}" stroke-width="1.2"/>`,
    ...xticks.map((t) => `<text x="${X(t).toFixed(1)}" y="${h - pad.b + 24}" text-anchor="middle" font-size="15" fill="${MUTED}">${fmtX(t)}</text>`),
    ...series.map((s, i) => {
      const p = [...s.points].sort((a, b) => a[0] - b[0]);
      const d = p.map((q, j) => `${j ? "L" : "M"}${X(q[0]).toFixed(1)},${Y(q[1]).toFixed(1)}`).join("");
      return `<path d="${d}" fill="none" stroke="${COLORS[i % 6]}" stroke-width="2.4"/>` +
             p.map((q) => marker(MARKS[i % 6], X(q[0]).toFixed(1), Y(q[1]).toFixed(1), COLORS[i % 6])).join("");
    }),
    ...series.map((s, i) => `<g transform="translate(${pad.l + 18},${pad.t + 14 + i * 22})">` +
      `<line x1="0" x2="26" y1="0" y2="0" stroke="${COLORS[i % 6]}" stroke-width="2.4"/>` +
      marker(MARKS[i % 6], 13, 0, COLORS[i % 6]) +
      `<text x="34" y="5" font-size="15" fill="${INK}">${s.name}</text></g>`),
    `<text x="${w / 2}" y="${h - 16}" text-anchor="middle" font-size="16" fill="${MUTED}">${xLabel}</text>`,
    `<text x="26" y="${h / 2}" text-anchor="middle" font-size="16" fill="${MUTED}" transform="rotate(-90 26 ${h / 2})">${yLabel}</text>`,
  ].join("\n  ");

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}"
     font-family="Helvetica, Arial, sans-serif">
  <rect width="${w}" height="${h}" fill="#ffffff"/>
  ${body}
</svg>\n`;
}

// ── the figures ───────────────────────────────────────────────────────────────────────────────
mkdirSync(OUT, { recursive: true });
const write = (name, svg) => {
  if (!svg) return;
  writeFileSync(join(OUT, name), svg);
  console.log(`wrote ${join(OUT, name)}`);
};

// least squares y = a + bx, with R², so the fit is reported rather than eyeballed
function fit(points) {
  const n = points.length;
  const mx = points.reduce((s, p) => s + p[0], 0) / n, my = points.reduce((s, p) => s + p[1], 0) / n;
  const b = points.reduce((s, p) => s + (p[0] - mx) * (p[1] - my), 0) /
            points.reduce((s, p) => s + (p[0] - mx) ** 2, 0);
  const a = my - b * mx;
  const ss = points.reduce((s, p) => s + (p[1] - my) ** 2, 0);
  const rs = points.reduce((s, p) => s + (p[1] - (a + b * p[0])) ** 2, 0);
  return { a, b, r2: 1 - rs / ss };
}

const ks = [...new Set(rows.filter((r) => r.suite === "reuse").map((r) => +r.case.slice(2)))].sort((a, b) => a - b);
if (ks.length) {
  const series = [];
  for (const c of cellsRun) {
    for (const [arm, name] of [["t_redecode", "re-decode"], ["t_reuse", "reuse"]]) {
      const points = ks.map((k) => [k, med((r) => r.suite === "reuse" && r.case === `k=${k}` &&
        r.cells === c && r.metric === arm)]).filter((p) => p[1] != null);
      if (points.length > 1) {
        series.push({ name: `${name}, ${label(c)}`, points });
        const f = fit(points);
        console.log(`  ${name.padEnd(10)} ${label(c).padStart(10)}:  ` +
                    `t = ${f.a.toFixed(2)} + ${f.b.toFixed(3)}·k ms   R² = ${f.r2.toFixed(4)}`);
      }
    }
  }
  write(`${PREFIX}-reuse.svg`, chart({ xLabel: "derived layers (k)", yLabel: "milliseconds", series }));
}

const tcases = [...new Set(rows.filter((r) => r.suite === "throughput").map((r) => r.case))];
if (tcases.length) {
  write(`${PREFIX}-throughput.svg`, chart({
    xLabel: "cells", yLabel: "million cells per second", logX: true, logY: true,
    series: tcases.map((name) => ({
      name,
      points: cellsRun.map((c) => [c, med((r) => r.suite === "throughput" && r.case === name &&
        r.cells === c && r.metric === "rate")]).filter((p) => p[1] != null).map(([x, y]) => [x, y / 1e6]),
    })).filter((s) => s.points.length > 1),
  }));
}

if (rows.some((r) => r.suite === "decode")) {
  write(`${PREFIX}-decode.svg`, chart({
    xLabel: "cells", yLabel: "milliseconds", logX: true,
    series: ["cold", "warm"].map((arm) => ({
      name: `${arm} cache`,
      points: cellsRun.map((c) => [c, med((r) => r.suite === "decode" && r.case === arm &&
        r.cells === c && r.metric === "t_total")]).filter((p) => p[1] != null),
    })).filter((s) => s.points.length > 1),
  }));
}

const providers = [...new Set(rows.filter((r) => r.suite === "map").map((r) => r.case))];
for (const metric of ["t_mount", "t_render", "t_restyle"]) {
  const series = providers.map((p) => ({
    name: p,
    points: cellsRun.map((c) => [c, med((r) => r.suite === "map" && r.case === p &&
      r.cells === c && r.metric === metric)]).filter((q) => q[1] != null),
  })).filter((s) => s.points.length > 1);
  if (series.length) {
    write(`${PREFIX}-map-${metric.slice(2)}.svg`,
          chart({ xLabel: "cells", yLabel: "milliseconds", logX: true, series }));
  }
}

const sessions = [...new Set(rows.map((r) => r.session))].filter(Boolean);
if (sessions.length > 1) console.log(`\n${sessions.length} sessions in this file: ${sessions.join(", ")}`);
